// Obtenemos todos los items de entrada
const items = $input.all();

// Tomamos el primer item (el que trae la respuesta de ChatGPT)
let text = items[0].json.output;

// Si el contenido viene como array, tomamos el primer elemento
if (Array.isArray(items[0].json) && items[0].json[0]?.output) {
  text = items[0].json[0].output;
}

// Limpiamos saltos de línea y caracteres escapados
text = text.trim();

let parsed;
try {
  parsed = JSON.parse(text);
} catch (err) {
  // Segundo intento si el JSON viene escapado o con ```json
  try {
    parsed = JSON.parse(
      text
        .replace(/^```json/, "")
        .replace(/```$/, "")
        .replace(/\n/g, "")
        .replace(/\\"/g, '"')
        .replace(/\\n/g, "")
    );
  } catch (e) {
    throw new Error("❌ No se pudo parsear el JSON. Contenido recibido: " + text);
  }
}

// Retornamos el JSON ya parseado como un nuevo item
return [{ json: parsed }];

// Lee todos los items que entran al nodo (compatible con "Run Once for All Items")
const inputs = $input.all();

const results = [];

for (const entry of inputs) {
  const data = entry.json;

  // tabs puede venir como string (JSON) o ya como array; manejamos ambos casos
  let tabs;
  if (typeof data.tabs === 'string') {
    try {
      tabs = JSON.parse(data.tabs);
    } catch (e) {
      throw new Error('Error al parsear data.tabs: ' + e.message + '\nContenido: ' + data.tabs);
    }
  } else {
    tabs = data.tabs || [];
  }

  // contenidoId puede estar en con_id o en contenidoId según tu flujo
  const contenidoId = data.con_id ?? data.contenidoId ?? null;

  for (const tab of tabs) {
    results.push({
      json: {
        nombre: tab.nombre,
        detalles: tab.detalles,
        contenidoId: contenidoId
      }
    });
  }
}

// Devolver un array de items (uno por cada tab)
return results;

const inputs = $input.all();
const results = [];

for (const tab of inputs) {
  const data = tab.json;
  const { nombre, detalles, contenidoId } = data;

  if (Array.isArray(detalles)) {
    for (const detalle of detalles) {
      results.push({
        json: {
          tabNombre: nombre,
          contenidoId,
          tipo: detalle.tipo,
          titulo: detalle.titulo,
          texto: detalle.texto
        }
      });
    }
  }
}

return results;

const inputs = $input.all();

/** @type {Record<string, any>} */
const grouped = {};

for (const entry of inputs) {
  const data = entry.json;
  const tabNombre = data.tabNombre;
  const contenidoId = data.contenidoId;

  if (!grouped[tabNombre]) {
    grouped[tabNombre] = {
      tabNombre: tabNombre,
      contenidoId: contenidoId,
      detalles: []
    };
  }

  grouped[tabNombre].detalles.push({
    tipo: data.tipo,
    titulo: data.titulo,
    texto: data.texto
  });
}

const results = Object.keys(grouped).map(key => ({ json: grouped[key] }));
return results;

// @ts-ignore
const rawTabs = $node["HTTP Request — Crear Tab"].json;

// Asegurar que siempre tengamos un array limpio
const tabsCreados = Array.isArray(rawTabs)
  ? rawTabs.map(t => t.json || t)
  : [rawTabs.json || rawTabs];

// Tomar el primer item de Code3 (asumiendo que todo viene en un solo nodo)
const code3Tab = $('Code3').first().json;

if (!code3Tab || !Array.isArray(code3Tab.detalles)) {
  return [{
    json: { log: "⚠️ No hay items en el nodo Code3" }
  }];
}

const tabNombre = code3Tab.tabNombre;
const contenidoId = code3Tab.contenidoId;

const tabEncontrado = tabsCreados.find(t => t.cot_nombre_tab === tabNombre);

if (!tabEncontrado) {
  return [{
    json: {
      log: `⚠️ No se encontró un tab con el nombre "${tabNombre}"`,
      tabNombre,
    }
  }];
}

const tabId = tabEncontrado.cot_id;

const results = [];

// Recorremos todos los detalles sin repetir
for (const detalle of code3Tab.detalles) {
  results.push({
    json: {
      log: `✅ Tab encontrado: ${tabNombre} (ID ${tabId})`,
      tabNombre,
      contenidoId,
      tabId,
      titulo: detalle.titulo,
      texto: detalle.texto
    }
  });
}

return results;
